from unittest.mock import patch
from collector.gather_disk import DiskError, gather, normalize_filesystems
rows = [
    {'mount': '/var', 'size_bytes': 20, 'used_bytes': 20},
    {'mount': '/', 'size_bytes': 10, 'used_bytes': 0},
]
with patch('collector.gather_disk.load_fixture_rows', return_value=rows):
    assert gather() == {'filesystems': [rows[1], rows[0]]}
assert rows[0]['mount'] == '/var'
with patch('collector.gather_disk.load_fixture_rows', return_value=[{'mount': '/', 'size_bytes': 10, 'used_bytes': 11}]):
    try:
        gather()
    except DiskError:
        pass
    else:
        raise AssertionError('gather must reject used_bytes above size_bytes')
for bad in ([], [{'mount': 'relative', 'size_bytes': 10, 'used_bytes': 0}], [rows[0], rows[0]]):
    try:
        normalize_filesystems(bad)
    except DiskError:
        pass
    else:
        raise AssertionError(f'accepted invalid filesystems: {bad}')
print('Disk checks passed; no collection run yet.')
